// 📁 src/context/AuthContext.jsx
import { createContext, useContext, useEffect, useMemo, useState } from "react";
import api from "@/utils/api";

const AuthContext = createContext(null);
export const useAuth = () => useContext(AuthContext);

export function AuthProvider({ children }) {
  const [status, setStatus] = useState("checking"); // "checking" | "authenticated" | "unauthenticated"
  const [admin, setAdmin] = useState(null);

  // ——— helpers stockage token ———
  const getToken = () =>
    localStorage.getItem("adminToken") || sessionStorage.getItem("adminToken");

  const clearToken = () => {
    localStorage.removeItem("adminToken");
    sessionStorage.removeItem("adminToken");
    localStorage.removeItem("adminEmail");
    sessionStorage.removeItem("adminEmail");
  };

  // ——— API: qui suis-je ? ———
  const fetchMe = async () => {
    try {
      const { data } = await api.get("/admin/me");
      setAdmin(data?.admin || null);
      setStatus("authenticated");
    } catch {
      clearToken();
      setAdmin(null);
      setStatus("unauthenticated");
    }
  };

  // ——— au montage: si token → /admin/me, sinon non-auth ———
  useEffect(() => {
    const token = getToken();
    if (!token) {
      setStatus("unauthenticated");
      setAdmin(null);
      return;
    }
    fetchMe();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // ——— actions exposées ———
  const login = async ({ token, admin: adminPayload, remember = true }) => {
    // Utilise ceci depuis ta page de login après succès backend
    // ex: login({ token: data.token, admin: data.admin, remember: true })
    try {
      if (remember) localStorage.setItem("adminToken", token);
      else sessionStorage.setItem("adminToken", token);

      if (adminPayload?.email) {
        if (remember) localStorage.setItem("adminEmail", adminPayload.email);
        else sessionStorage.setItem("adminEmail", adminPayload.email);
      }

      setAdmin(adminPayload || null);
      setStatus("authenticated");
    } catch {
      clearToken();
      setAdmin(null);
      setStatus("unauthenticated");
    }
  };

  const logout = () => {
    // Appelé depuis AdminSidebar (ou ailleurs)
    clearToken();
    setAdmin(null);
    setStatus("unauthenticated");
    // pas de navigate ici (la route protégée redirigera vers /admin/login)
  };

  const value = useMemo(
    () => ({ status, admin, setStatus, setAdmin, login, logout }),
    [status, admin]
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export default AuthProvider;
